"""YAML front-matter and metadata parsing for library and generated files."""
from __future__ import annotations

from pathlib import Path
from typing import Any

import yaml
from markdown_it import MarkdownIt
from mdit_py_plugins.front_matter import front_matter_plugin

_MD = MarkdownIt("commonmark").use(front_matter_plugin)


def _tokens(text: str):
    """Block tokens for *text*, with line endings normalized the way the parser sees them."""
    return _MD.parse(text.replace("\r\n", "\n").replace("\r", "\n"))


def _front_matter(text: str) -> dict[str, Any]:
    """The parsed front-matter mapping — ``{}`` for no front matter or malformed YAML."""
    tokens = _tokens(text)
    if not tokens or tokens[0].type != "front_matter":
        return {}
    try:
        data = yaml.safe_load(tokens[0].content + "\n") or {}
    except yaml.YAMLError:
        return {}
    return data if isinstance(data, dict) else {}


def frontmatter_mapping(text: str) -> dict[str, Any]:
    """The whole parsed front matter of a markdown source — ``{}`` when there is none."""
    return _front_matter(text)


def read_yaml(path: Path) -> dict[str, Any]:
    if not path.exists():
        raise SystemExit(f"Missing config: {path}")
    with path.open(encoding="utf-8") as handle:
        data = yaml.safe_load(handle) or {}
    if not isinstance(data, dict):
        raise SystemExit(f"Config must be a YAML mapping: {path}")
    return data


def banner_sources(text: str) -> list[str]:
    """Library source paths listed in a generated file's leading HTML banner."""
    tokens = _tokens(text)
    if not tokens or tokens[0].type != "html_block":
        return []
    banner = tokens[0].content
    if not banner.startswith("<!--") or "generated by farrier" not in banner:
        return []
    out: list[str] = []
    for line in banner.splitlines():
        fields = line.split()
        if line[:1].isspace() and len(fields) == 1 and fields[0].startswith("library/"):
            out.append(fields[0])
    return out


LOCAL_INSTRUCTION_FILES = ("AGENTS.md", "CLAUDE.md")


def mapping_skill_names(mapping: dict[str, Any]) -> list[str]:
    """The installed skill names a localInstructions mapping selects."""
    if mapping.get("skills"):
        return [str(name) for name in mapping["skills"]]
    if mapping.get("skill"):
        return [str(mapping["skill"])]
    return []


def mapping_policy_names(mapping: dict[str, Any]) -> list[str]:
    """The policy names a localInstructions mapping selects."""
    if mapping.get("policies"):
        return [str(name) for name in mapping["policies"]]
    if mapping.get("policy"):
        return [str(mapping["policy"])]
    return []


def mapping_prompt_names(mapping: dict[str, Any]) -> list[str]:
    """The installed prompt names a localInstructions mapping selects."""
    if mapping.get("prompts"):
        return [str(name) for name in mapping["prompts"]]
    if mapping.get("prompt"):
        return [str(mapping["prompt"])]
    return []


_README_ALIASES = {"inline": True, "import": True, "none": False}


def mapping_include_readme(mapping: dict[str, Any]) -> bool:
    """Whether a localInstructions mapping folds in the sibling README.md."""
    value = mapping.get("includeReadme", True)
    if isinstance(value, bool):
        return value
    key = str(value)
    if key not in _README_ALIASES:
        raise SystemExit(
            f"localInstructions.includeReadme must be true or false "
            f"(got {value!r}; the {'/'.join(_README_ALIASES)} spellings are the "
            "old mechanism-picking form and still work)"
        )
    return _README_ALIASES[key]


def _as_text(value: Any) -> str:
    """A header value as the single string the renderer templates and re-quotes."""
    if value is None:
        return ""
    if isinstance(value, str):
        return value
    if isinstance(value, (list, dict)):
        return yaml.safe_dump(value, default_flow_style=True, allow_unicode=True).strip()
    return str(value)


def split_front_matter(content: str) -> tuple[dict[str, str], str]:
    """``({key: value}, body)`` — front matter as a flat string map, plus the rest."""
    tokens = _tokens(content)
    if not tokens or tokens[0].type != "front_matter" or not tokens[0].map:
        return {}, content
    body = "\n".join(
        content.replace("\r\n", "\n").replace("\r", "\n").split("\n")[tokens[0].map[1]:]
    )
    return ({key: _as_text(value) for key, value in _front_matter(content).items()},
            body.removeprefix("\n"))


def normalize_tags(value: Any) -> list[str]:
    """The tag list a `tags:` value denotes — lowercased, stripped, order-preserving."""
    if isinstance(value, str):
        items: list[Any] = value.split(",")
    elif isinstance(value, (list, tuple)):
        items = list(value)
    else:
        return []
    tags: list[str] = []
    for item in items:
        tag = str(item).strip().strip('"').strip("'").lower()
        if tag and tag not in tags:
            tags.append(tag)
    return tags


def frontmatter_tags(text: str) -> list[str]:
    """The `tags:` a file's front matter declares, normalized by :func:`normalize_tags`."""
    return normalize_tags(_front_matter(text).get("tags"))


def frontmatter_metadata(text: str) -> dict[str, Any]:
    """Parse a generated file's YAML front matter and return its `metadata` mapping."""
    meta = _front_matter(text).get("metadata")
    return meta if isinstance(meta, dict) else {}


def first_heading(body: str, fallback: str) -> str:
    """The body's first level-1 heading, or *fallback*."""
    tokens = _tokens(body)
    for i, tok in enumerate(tokens):
        if tok.type == "heading_open" and tok.tag == "h1":
            return tokens[i + 1].content.strip() if i + 1 < len(tokens) else fallback
    return fallback


def front_matter_end(content: str) -> int:
    """The line index where the document proper begins — ``0`` when there is no fence."""
    tokens = _tokens(content)
    if not tokens or tokens[0].type != "front_matter" or not tokens[0].map:
        return 0
    return tokens[0].map[1]
